        suite.addTest(FileTests.interpreterSuite(testDir1, failsOnly, false));
        suite.addTest(FileTests.interpreterSuite(testDir2, failsOnly, false));
        suite.addTest(FileTests.interpreterSuite(testDir3, failsOnly, false));
        //$JUnit-END$
        return suite;
    }
}
